fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    // If length is 0 or 1, return unchanged
    if n <= 1 {
        return numbers;
    }

    // Result length is 2*n - 1
    let mut result = Vec::with_capacity(2 * n - 1);

    for (i, &num) in numbers.iter().enumerate() {
        // Push the original element at even indices
        result.push(num);
        // Between elements (except after the last), push delimiter
        if i != n - 1 {
            result.push(delimiter);
        }
    }

    result
}